<?php
declare(strict_types=1);
require_once __DIR__.'/backup-crypto.php';
function b_dir():string{$base=r_private_storage();$dir=$base.'/backups';if(is_link($dir)){throw new DomainException('Backup storage must not be a symbolic link.');}if(!is_dir($dir)&&!mkdir($dir,0700)){throw new DomainException('Protected backup directory is not writable.');}file_put_contents($dir.'/.htaccess',"Require all denied\n");return $dir;}
function b_setting(PDO $pdo,string $value,?string $run=null):void{$stmt=$pdo->prepare("INSERT INTO admin_settings(setting_key,setting_value) VALUES ('backup_until',?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)");$stmt->execute([$value]);if($run!==null){$stmt=$pdo->prepare("INSERT INTO admin_settings(setting_key,setting_value) VALUES ('backup_run',?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)");$stmt->execute([$run]);}}
function b_fetch(PDO $pdo,string $id,bool $lock=false):array{$stmt=$pdo->prepare('SELECT * FROM backup_runs WHERE id=?'.($lock?' FOR UPDATE':''));$stmt->execute([$id]);$r=$stmt->fetch();if(!$r){throw new DomainException('Backup not found.');}return $r;}
function b_file(string $logical):string{global $configPath;if($logical==='config/config.php'){return $configPath;}if(!preg_match('~\Aprivate/([a-f0-9]{64}\.bin|cms/[a-f0-9]{64}-(?:480|960|1600)\.jpg)\z~D',$logical,$m)){throw new DomainException('Invalid backup file path.');}$base=r_private_storage();$path=$base.'/'.$m[1];if(is_link($path)){throw new DomainException('Do not back up a symlink as private data.');}return $path;}
function b_start(PDO $pdo,array $user):array{
 global $config;v_confirm($pdo,$user);b_dir();if(!function_exists('openssl_encrypt')||!in_array('aes-256-gcm',openssl_get_cipher_methods(),true)){throw new DomainException('Authenticated backup encryption requires PHP OpenSSL.');}if(hash_equals(field('confirm_code'),field('passphrase'))){throw new DomainException('Choose a backup passphrase different from your administrator private code.');}$salt=random_bytes(16);$key=b_key(field('passphrase'),$salt);
 p_lock($pdo);try{
 if((int)setting($pdo,'backup_until','0')>time()){throw new DomainException('A backup is already holding maintenance. Resume or cancel it.');}
 $lease=$pdo->prepare('SELECT COUNT(*) FROM maintenance_writes WHERE request_id<>?');$lease->execute([$_SERVER['SYA_WRITE_LEASE']??'']);if((int)$lease->fetchColumn()){throw new DomainException('Another write request is still in progress. Retry backup start after it finishes.');}
 // Do not freeze halfway through external sends or prior physical deletion cleanup.
 foreach(["SELECT COUNT(*) FROM newsletter_deliveries WHERE state='sending' AND lease_until>UNIX_TIMESTAMP()","SELECT COUNT(*) FROM contact_events WHERE delivery_state='sending' AND lease_until>UNIX_TIMESTAMP()","SELECT COUNT(*) FROM audition_notifications WHERE state='sending' AND lease_until>UNIX_TIMESTAMP()","SELECT COUNT(*) FROM privacy_file_deletions WHERE state<>'removed'"] as $sql){if((int)$pdo->query($sql)->fetchColumn()){throw new DomainException('Finish active sends and pending file-deletion cleanup before backing up.');}}
 $tables=$pdo->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);sort($tables);foreach($tables as $table){if(!preg_match('/\A[a-z0-9_]+\z/D',$table)){throw new DomainException('Unsupported database table name.');}}
 $files=['config/config.php'];foreach($pdo->query('SELECT storage_key FROM recruitment_attachments ORDER BY id') as $row){$files[]='private/'.$row['storage_key'];if(count($files)>5000){throw new DomainException('More than 5000 files: arrange supervised off-host backup instead.');}}
 foreach($pdo->query('SELECT storage_key FROM media_assets ORDER BY id') as $row){foreach([480,960,1600] as $size){$files[]='private/cms/'.$row['storage_key'].'-'.$size.'.jpg';}if(count($files)>5000){throw new DomainException('More than 5000 files: arrange supervised off-host backup instead.');}}
 $pdo->exec("UPDATE backup_runs SET state='expired' WHERE state='active' AND expires_at<=UNIX_TIMESTAMP()");$manifest=['tables'=>$tables,'table'=>0,'offset'=>0,'files'=>$files,'file'=>0,'file_offset'=>0,'phase'=>'database'];$id=bin2hex(random_bytes(16));$expires=time()+1200;$days=max(1,min(30,(int)($config['backups']['retention_days']??7)));
 $stmt=$pdo->prepare('INSERT INTO backup_runs(id,manifest_json,salt,key_check,expires_at,created_by,retention_due_at) VALUES (?,?,?,?,?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL ? DAY))');$stmt->execute([$id,json_encode($manifest),bin2hex($salt),hash_hmac('sha256','sya-backup-check',$key),$expires,$user['id'],$days]);b_setting($pdo,(string)$expires,$id);audit($pdo,(int)$user['id'],'backup.started');$pdo->commit();$_SESSION['backup_key']=['run'=>$id,'key'=>base64_encode($key),'expires'=>$expires];return ['Backup started. Writes are paused for at most 20 minutes. Prepare encrypted parts, download every part, then record the off-host copy and restoration test.'];
 }catch(Throwable $e){if($pdo->inTransaction()){$pdo->rollBack();}throw $e;}
}
function b_part_payload(PDO $pdo,array $run,array &$m,int $number):array{
 $payload=['version'=>1,'run'=>$run['id'],'part'=>$number];
 if($m['phase']==='database'){
  $table=$m['tables'][$m['table']];$offset=(int)$m['offset'];$sql='';
  if($offset===0){$ddl=$pdo->query('SHOW CREATE TABLE `'.$table.'`')->fetch(PDO::FETCH_NUM)[1];$sql=$ddl.";\n";}
  // Backup bookkeeping and ephemeral authentication/verification challenges are not restored.
  $skip=in_array($table,['backup_runs','backup_parts','auth_rate_limits','recruitment_tracking_challenges','communication_tokens','maintenance_writes'],true);
  $rows=[];if(!$skip){$pk=$pdo->query('SHOW KEYS FROM `'.$table.'` WHERE Key_name=\'PRIMARY\'')->fetchAll();$keys=array_column($pk,'Column_name');$order=$keys?' ORDER BY '.implode(',',array_map(fn($n)=>'`'.$n.'`',$keys)):'';$rows=$pdo->query('SELECT * FROM `'.$table.'`'.$order.' LIMIT 51 OFFSET '.$offset)->fetchAll();}
  $count=0;foreach(array_slice($rows,0,50) as $row){if($table==='admin_settings'&&in_array($row['setting_key'],['backup_until','backup_run'],true)){$count++;continue;}$values=array_map(fn($v)=>$v===null?'NULL':"X'".bin2hex((string)$v)."'",array_values($row));$line='INSERT INTO `'.$table.'` ('.implode(',',array_map(fn($c)=>'`'.$c.'`',array_keys($row))).') VALUES ('.implode(',',$values).");\n";if(strlen($line)>3000000){throw new DomainException('A database row exceeds the backup part limit. Use supervised export.');}if(strlen($sql)+strlen($line)>3500000&&$count){break;}$sql.=$line;$count++;}
  $more=count($rows)>$count;$m['offset']+=$count;if(!$more){$m['table']++;$m['offset']=0;if($m['table']>=count($m['tables'])){$m['phase']='files';}}
  return $payload+['kind'=>'sql','table'=>$table,'offset'=>$offset,'rows'=>$count,'sql'=>$sql];
 }
 if($m['phase']==='files'){
  if($m['file']>=count($m['files'])){$m['phase']='complete';}
  else{$logical=$m['files'][$m['file']];$path=b_file($logical);if(!is_file($path)||!is_readable($path)){throw new DomainException('A referenced private file is missing/unreadable. Cancel and repair before trusting this backup.');}$size=filesize($path);$offset=(int)$m['file_offset'];$stream=fopen($path,'rb');if(!$stream){throw new DomainException('Private file could not be read.');}fseek($stream,$offset);$bytes=fread($stream,1048576);fclose($stream);if($bytes===false){throw new DomainException('Private file read failed.');}$m['file_offset']+=strlen($bytes);if($m['file_offset']>=$size){$m['file']++;$m['file_offset']=0;if($m['file']>=count($m['files'])){$m['phase']='complete';}}return $payload+['kind'=>'file','path'=>$logical,'offset'=>$offset,'total'=>$size,'sha256'=>hash_file('sha256',$path),'data'=>base64_encode($bytes)];}
 }
 $stmt=$pdo->prepare('SELECT part_number,plain_hash FROM backup_parts WHERE run_id=? ORDER BY part_number');$stmt->execute([$run['id']]);return $payload+['kind'=>'complete','hashes'=>$stmt->fetchAll(),'files'=>$m['files'],'schema_versions'=>(int)$pdo->query('SELECT COUNT(*) FROM schema_migrations')->fetchColumn()];
}
function b_action(PDO $pdo,array $user):array{
 c_super($user);$action=field('action');if($action==='backup_start'){return b_start($pdo,$user);}if($action==='backup_clear_leases'){v_confirm($pdo,$user);if(field('lease_review')!=='1'){throw new DomainException('Confirm with hosting support that stale requests have ended before clearing their write leases.');}$stmt=$pdo->prepare('DELETE FROM maintenance_writes WHERE expires_at<? LIMIT 100');$stmt->execute([time()]);audit($pdo,(int)$user['id'],'backup.stale_leases_cleared');return ['Removed up to 100 expired write leases after operator review. Active leases were retained.'];}$id=field('run_id');$run=b_fetch($pdo,$id);
 if($action==='backup_resume'){v_confirm($pdo,$user);$key=b_key(field('passphrase'),hex2bin($run['salt']));if(!hash_equals($run['key_check'],hash_hmac('sha256','sya-backup-check',$key))){throw new DomainException('Wrong backup passphrase.');}if($run['state']!=='active'||(int)$run['expires_at']<=time()){throw new DomainException('Backup expired or is not active. Start a fresh complete backup.');}$_SESSION['backup_key']=['run'=>$id,'key'=>base64_encode($key),'expires'=>(int)$run['expires_at']];return ['Backup key restored to this short-lived staff session.'];}
 if($action==='backup_record'){v_confirm($pdo,$user);$off=c_text(field('offhost_note'),500);$restore=c_text(field('restore_note'),1000);$stmt=$pdo->prepare('UPDATE backup_runs SET offhost_note=?,restore_note=? WHERE id=?');$stmt->execute([$off,$restore,$id]);audit($pdo,(int)$user['id'],'backup.recorded');return ['Backup custody/restoration notes saved. Record only actions actually completed; a note does not perform a copy or test.'];}
 if($action==='backup_cancel'){v_confirm($pdo,$user);p_lock($pdo);try{$stmt=$pdo->prepare("UPDATE backup_runs SET state='cancelled' WHERE id=? AND state='active'");$stmt->execute([$id]);if($stmt->rowCount()&&setting($pdo,'backup_run','')===$id){b_setting($pdo,'0');}audit($pdo,(int)$user['id'],'backup.cancelled');$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction()){$pdo->rollBack();}throw $e;}if(($_SESSION['backup_key']['run']??'')===$id){unset($_SESSION['backup_key']);}return ['Backup cancelled; do not use its incomplete parts for restoration. Writes resume only if this run owned the pause.'];}
 if($action==='backup_delete'){v_confirm($pdo,$user);if($run['state']==='active'&&(int)$run['expires_at']>time()){throw new DomainException('Cancel the active backup first.');}if(strtotime($run['retention_due_at'].' UTC')>time()&&field('delete_confirm')!=='1'){throw new DomainException('Confirm deletion of retained encrypted backup parts.');}$stmt=$pdo->prepare('SELECT * FROM backup_parts WHERE run_id=? LIMIT 20');$stmt->execute([$id]);foreach($stmt->fetchAll() as $part){$path=b_dir().'/'.$part['storage_key'].'.syab';if(is_file($path)&&!@unlink($path)){throw new DomainException('Encrypted part deletion failed. Retry after checking permissions.');}$stmt=$pdo->prepare('DELETE FROM backup_parts WHERE id=?');$stmt->execute([$part['id']]);}$stmt=$pdo->prepare('SELECT COUNT(*) FROM backup_parts WHERE run_id=?');$stmt->execute([$id]);if(!(int)$stmt->fetchColumn()){$stmt=$pdo->prepare("UPDATE backup_runs SET state='deleted' WHERE id=?");$stmt->execute([$id]);}audit($pdo,(int)$user['id'],'backup.parts_deleted');return ['Deleted up to 20 encrypted parts. Repeat until the run is marked deleted. Off-host copies need separate expiry/deletion.'];}
 if($action!=='backup_step'){throw new DomainException('Unknown backup action.');}
 $session=$_SESSION['backup_key']??[];if(($session['run']??'')!==$id||(int)($session['expires']??0)<=time()){throw new DomainException('Resume with the backup passphrase to prepare more parts.');}$key=base64_decode($session['key'],true);if(!is_string($key)||strlen($key)!==32){throw new DomainException('Backup key unavailable.');}
 p_lock($pdo);$path=null;try{
 $run=b_fetch($pdo,$id,true);if($run['state']!=='active'||(int)$run['expires_at']<=time()||((int)setting($pdo,'backup_until','0')<=time()||setting($pdo,'backup_run','')!==$id)){throw new DomainException('Backup is incomplete/expired. Cancel it and start again; writes may have resumed.');}
 $m=json_decode($run['manifest_json'],true);$stmt=$pdo->prepare('SELECT COUNT(*) FROM backup_parts WHERE run_id=?');$stmt->execute([$id]);$number=(int)$stmt->fetchColumn();$payload=b_part_payload($pdo,$run,$m,$number);$plain=json_encode($payload,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);$encrypted=b_encrypt($plain,$key,hex2bin($run['salt']));$storage=bin2hex(random_bytes(32));$path=b_dir().'/'.$storage.'.syab';if(file_put_contents($path,$encrypted,LOCK_EX)!==strlen($encrypted)){throw new DomainException('Encrypted backup part could not be stored.');}chmod($path,0600);
 $stmt=$pdo->prepare('INSERT INTO backup_parts(run_id,part_number,storage_key,plain_hash,bytes) VALUES (?,?,?,?,?)');$stmt->execute([$id,$number,$storage,hash('sha256',$plain),strlen($encrypted)]);$complete=$payload['kind']==='complete';$stmt=$pdo->prepare('UPDATE backup_runs SET manifest_json=?,state=?,completed_at=IF(?,UTC_TIMESTAMP(),completed_at) WHERE id=?');$stmt->execute([json_encode($m),$complete?'complete':'active',(int)$complete,$id]);if($complete){b_setting($pdo,'0');unset($_SESSION['backup_key']);audit($pdo,(int)$user['id'],'backup.completed');}$pdo->commit();return [$complete?'Encrypted backup complete. Download every numbered part, copy off-host and test restoration before relying on it.':'Encrypted part #'.$number.' prepared. Download it and continue preparing the next part.'];
 }catch(Throwable $e){if($pdo->inTransaction()){$pdo->rollBack();}if($path&&is_file($path)){unlink($path);}throw $e;}
}
